package com.jamshed.hrms.controller; import com.jamshed.hrms.repository.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/dashboard") public class DashboardController {private final EmployeeRepository e;private final LeaveRequestRepository l;private final CandidateRepository c;private final AttendanceRepository a;public DashboardController(EmployeeRepository e,LeaveRequestRepository l,CandidateRepository c,AttendanceRepository a){this.e=e;this.l=l;this.c=c;this.a=a;}@GetMapping public Map<String,Object> stats(){return Map.of("employees",e.count(),"leaveRequests",l.count(),"candidates",c.count(),"attendanceRecords",a.count(),"message","Welcome to the fresh HRMS portal");}}
